update public.cities set
  enabled=true,public_status='published',
  module_config='{"calendar":true,"places":true,"community":true,"buddy":true,"marketplace":true,"housing":true,"jobs":false,"chat":true,"watcher":true,"settings":true,"offers":false}'::jsonb,
  brand_config=brand_config||'{"seoTitle":"StudentHub Olomouc – prakticky pro studenty","seoDescription":"Ověřené termíny, místa, komunita a praktické služby pro studenty v Olomouci."}'::jsonb,
  updated_at=now()
where id='olomouc';

insert into public.city_configuration_audit(city_id,actor_id,action,previous_config,new_config)
select 'olomouc',null,'published','{"publicStatus":"draft","enabled":false}'::jsonb,
  jsonb_build_object('publicStatus','published','enabled',true,'jobs',false,'offers',false,'verifiedAt','2026-09-28')
where not exists (
  select 1 from public.city_configuration_audit
  where city_id='olomouc' and action='published' and new_config->>'verifiedAt'='2026-09-28'
);

comment on column public.cities.module_config is
